CREATE OR REPLACE FUNCTION public.guard_hypercash_bank_link() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.crm_hypercash_payout_links WHERE company_key=NEW.company_key AND bank_transaction_id=NEW.polp_transaction_id) AND (TG_TABLE_NAME='polp_bank_reconciliations' OR to_jsonb(NEW)->>'kind' IS DISTINCT FROM 'transferencia_interna') THEN RAISE EXCEPTION 'hypercash_payout_not_revenue';END IF;RETURN NEW;END;$$;
CREATE TRIGGER hypercash_payout_override_guard BEFORE INSERT OR UPDATE ON public.polp_bank_classification_overrides FOR EACH ROW EXECUTE FUNCTION public.guard_hypercash_bank_link();
CREATE TRIGGER hypercash_payout_reconciliation_guard BEFORE INSERT OR UPDATE ON public.polp_bank_reconciliations FOR EACH ROW EXECUTE FUNCTION public.guard_hypercash_bank_link();
CREATE OR REPLACE FUNCTION public.audit_hypercash_subscription() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status OR NEW.client_id IS DISTINCT FROM OLD.client_id THEN INSERT INTO public.crm_hypercash_audit(subscription_id,event,before_data,after_data,actor) VALUES(NEW.subscription_id,'subscription_update',jsonb_build_object('status',OLD.status,'client',OLD.client_id),jsonb_build_object('status',NEW.status,'client',NEW.client_id),'hypercash_sync');END IF;RETURN NEW;END;$$;
CREATE TRIGGER hypercash_subscription_audit AFTER UPDATE ON public.crm_hypercash_subscriptions FOR EACH ROW EXECUTE FUNCTION public.audit_hypercash_subscription();
CREATE OR REPLACE FUNCTION public.audit_hypercash_client_link() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.client_id IS DISTINCT FROM OLD.client_id THEN INSERT INTO public.crm_hypercash_audit(charge_id,event,before_data,after_data,actor) VALUES(NEW.id,'client_link',jsonb_build_object('client',OLD.client_id),jsonb_build_object('client',NEW.client_id),'authenticated_review');END IF;RETURN NEW;END;$$;
CREATE TRIGGER hypercash_client_link_audit AFTER UPDATE ON public.crm_hypercash_charges FOR EACH ROW EXECUTE FUNCTION public.audit_hypercash_client_link();